source='''from collections import Counter, defaultdict

def _segments(n, occupied):
    out=[]
    i=0
    while i<n:
        if not occupied(i):
            i+=1
            continue
        a=i
        while i<n and occupied(i):
            i+=1
        out.append((a,i))
    return out

def _tile_groups(groups, size, n):
    out=[]
    for a,b in groups:
        length=b-a
        full=length==size
        partial=(b==n and length==size-1)
        if full or partial:
            out.append((a,b,a+1,b-(1 if full else 0)))
    return out

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    row_groups=_segments(h, lambda r: any(g[r][c] for c in range(w)))
    col_groups=_segments(w, lambda c: any(g[r][c] for r in range(h)))
    rh=Counter(b-a for a,b in row_groups).most_common(1)[0][0]
    cw=Counter(b-a for a,b in col_groups).most_common(1)[0][0]
    rows=_tile_groups(row_groups,rh,h)
    cols=_tile_groups(col_groups,cw,w)
    if not rows or not cols:
        return g
    cores={}
    freq=Counter()
    for ri,(ra,rb,ry0,ry1) in enumerate(rows):
        for ci,(ca,cb,cx0,cx1) in enumerate(cols):
            vals=[g[r][c] for r in range(ry0,ry1) for c in range(cx0,cx1)]
            if vals and len(set(vals))==1:
                color=vals[0]
                cores[ri,ci]=color
                freq[color]+=1
    if not freq:
        return g
    background=freq.most_common(1)[0][0]
    byrow=defaultdict(lambda: defaultdict(list))
    bycol=defaultdict(lambda: defaultdict(list))
    for (ri,ci),color in cores.items():
        if color!=background:
            byrow[ri][color].append(ci)
            bycol[ci][color].append(ri)
    for ri, groups in byrow.items():
        _,_,y0,y1=rows[ri]
        for color, positions in groups.items():
            positions.sort()
            for left,right in zip(positions,positions[1:]):
                _,_,_,left_end=cols[left]
                _,_,right_start,_=cols[right]
                for r in range(y0,y1):
                    for c in range(left_end,right_start):
                        if g[r][c]==0:
                            g[r][c]=color
    for ci, groups in bycol.items():
        _,_,x0,x1=cols[ci]
